/**
 * Free 计划快捷安装 / 试用入口
 * @author 恒哥
 */
import React from 'react';
import { Link } from 'gatsby';
import {
  PRODUCT_NAME,
  SHOPIFY_INSTALL_PAGE_PATH,
  SHOPIFY_APP_STORE_URL,
  SHOPIFY_APP_STORE_LABEL,
} from '../../constants/brand';
import './free-install-cta.css';

/**
 * @param {object} props
 * @param {'banner'|'card'|'inline'} [props.variant]
 * @param {string} [props.title]
 * @param {string} [props.className]
 * @param {boolean} [props.showPricingLink]
 * @param {boolean} [props.hideActions] 安装页正文上方仅展示说明，避免再链回 /install
 * @param {string} [props.primaryTo] 主按钮目标，默认 /install/
 * @param {string} [props.primaryLabel]
 */
export default function FreeInstallCta({
  variant = 'banner',
  title = `Try ${PRODUCT_NAME} on Free`,
  className = '',
  showPricingLink = true,
  hideActions = false,
  primaryTo = SHOPIFY_INSTALL_PAGE_PATH,
  primaryLabel = 'Install free now',
}) {
  const primaryIsHash = typeof primaryTo === 'string' && primaryTo.startsWith('#');

  return (
    <div className={`free-install-cta free-install-cta--${variant} ${className}`.trim()}>
      <div className="free-install-cta-copy">
        <span className="free-install-cta-badge">Free plan</span>
        <h3 className="free-install-cta-title">{title}</h3>
        <p className="free-install-cta-lead">
          $0 per month · 100 abandoned carts · 200 emails · <strong>no credit card</strong> ·
          billed only if you upgrade later inside Shopify
        </p>
      </div>
      {!hideActions && (
        <div className="free-install-cta-actions">
          {primaryIsHash ? (
            <a href={primaryTo} className="free-install-cta-btn free-install-cta-btn-primary">
              {primaryLabel}
            </a>
          ) : (
            <Link to={primaryTo} className="free-install-cta-btn free-install-cta-btn-primary">
              {primaryLabel}
            </Link>
          )}
          <a
            href={SHOPIFY_APP_STORE_URL}
            className="free-install-cta-btn free-install-cta-btn-secondary"
            target="_blank"
            rel="noopener noreferrer"
          >
            Try on {SHOPIFY_APP_STORE_LABEL}
          </a>
          {showPricingLink && variant !== 'inline' && (
            <Link to="/pricing/" className="free-install-cta-link">
              See Free vs Growth →
            </Link>
          )}
        </div>
      )}
    </div>
  );
}
